/* Alpine AJAX-compatible progressive enhancement. Native forms remain the fallback. */
document.addEventListener('submit', async function (event) { var form = event.target; var target = form.getAttribute('x-target'); if (!target || form.method.toLowerCase() !== 'get') return; event.preventDefault(); var response = await fetch(form.action || location.href, { headers: {'X-Alpine-Request':'true','X-Alpine-Target':target} }); if (response.ok) { var html = await response.text(); var wrapper = document.createElement('div'); wrapper.innerHTML = html; var current = document.getElementById(target); var replacement = wrapper.querySelector('#' + target); if (current && replacement) current.replaceWith(replacement); } });
